import 'package:family_veda/models/member.dart';
import 'package:family_veda/providers/auth_provider.dart';
import 'package:family_veda/providers/core_providers.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

final membersProvider = FutureProvider.autoDispose<List<Member>>((ref) async {
  // Read before sign-in finishes, this call is sent without a token, gets a 401 and
  // expires the session; the error would then stay cached for the whole run.
  final status = ref.watch(authProvider.select((state) => state.status));
  if (status != AuthStatus.authenticated) return const [];
  return ref.watch(patientApiProvider).getMembers();
});
